<script setup>
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { presenceTransition } from "../../utils/motion.js";
import KimaFileUpload from "../input/file-upload.ce.vue";
import KimaButton from "../core/button.ce.vue";
const props=defineProps({modelValue:{type:Array,default:()=>[]},upload:{type:Function,default:null},concurrency:{type:Number,default:2},accept:String,multiple:Boolean,disabled:Boolean,label:{type:String,default:"添加上传文件"}});const emit=defineEmits(["update:modelValue","change","progress","success","error","cancel"]);
let id=0;const tasks=ref([]),active=new Map();const queue=computed(()=>tasks.value.filter(t=>t.status==='queued'));
function add(files){const added=[...files].map(file=>({id:++id,file,status:'queued',progress:0,error:'',result:null}));tasks.value=[...tasks.value,...added];publish();pump();}
function publish(){const snapshot=tasks.value.map(({id,file,status,progress,error,result})=>({id,file,status,progress,error,result}));emit('update:modelValue',snapshot);emit('change',snapshot);}
function patch(task,values){Object.assign(task,values);publish();}
function pump(){while(active.size<Math.max(1,Math.floor(props.concurrency))&&queue.value.length){const task=queue.value[0];run(task);}}
async function run(task){if(typeof props.upload!=='function'){patch(task,{status:'error',error:'缺少 upload(file, { signal, onProgress }) 宿主处理函数'});emit('error',{task,error:new Error(task.error)});return;}const controller=new AbortController();active.set(task.id,controller);patch(task,{status:'uploading',error:'',progress:0});try{const result=await props.upload(task.file,{signal:controller.signal,onProgress:value=>{if(active.get(task.id)!==controller)return;const progress=Math.max(0,Math.min(100,Number(value)||0));task.progress=progress;emit('progress',{task,file:task.file,progress});publish();}});if(active.get(task.id)!==controller)return;patch(task,{status:'success',progress:100,result});emit('success',{task,result});}catch(error){if(active.get(task.id)!==controller)return;if(controller.signal.aborted){patch(task,{status:'cancelled'});emit('cancel',task);}else{patch(task,{status:'error',error:error?.message||String(error)});emit('error',{task,error});}}finally{if(active.get(task.id)===controller)active.delete(task.id);pump();}}
function cancel(task){if(task.status==='queued'){patch(task,{status:'cancelled'});emit('cancel',task);return;}if(task.status==='uploading'){const controller=active.get(task.id);if(!controller)return;active.delete(task.id);controller.abort();patch(task,{status:'cancelled'});emit('cancel',task);pump();}}
function retry(task){if(task.status!=='error'&&task.status!=='cancelled')return;patch(task,{status:'queued',progress:0,error:'',result:null});pump();}
function remove(task){cancel(task);tasks.value=tasks.value.filter(item=>item.id!==task.id);publish();}
watch(()=>props.modelValue,value=>{if(Array.isArray(value)&&value.length&&!tasks.value.length)tasks.value=value.map(item=>({...item,id:item.id||++id}));});onBeforeUnmount(()=>{for(const controller of active.values())controller.abort();active.clear();});defineExpose({add,cancel,retry,remove,tasks,pump});
</script>
<template><section class="kima-upload-manager" :aria-disabled="disabled||undefined"><KimaFileUpload :model-value="tasks.map(t=>t.file)" :label="label" :accept="accept" :multiple="multiple" :disabled="disabled" @update:model-value="files=>add(files.slice(tasks.filter(t=>t.status!=='cancelled').length))" /><TransitionGroup tag="ul" name="kima-list" v-bind="presenceTransition" class="kima-upload-manager__list"><li v-for="task in tasks" :key="task.id"><div class="kima-upload-manager__info"><strong>{{task.file.name}}</strong><progress max="100" :value="task.progress" :aria-label="`${task.file.name}上传进度`"></progress><span role="status">{{task.status==='queued'?'等待中':task.status==='uploading'?`${task.progress}%`:task.status==='success'?'已完成':task.status==='cancelled'?'已取消':task.error}}</span></div><div class="kima-upload-manager__actions"><KimaButton v-if="task.status==='uploading'||task.status==='queued'" variant="text" :disabled="disabled" @click="cancel(task)">取消</KimaButton><KimaButton v-if="task.status==='error'||task.status==='cancelled'" variant="text" :disabled="disabled" @click="retry(task)">重试</KimaButton><KimaButton variant="text" :disabled="disabled" :aria-label="`移除 ${task.file.name}`" @click="remove(task)">移除</KimaButton></div></li></TransitionGroup></section></template>
<style scoped lang="scss">
@use "../../styles/advanced-input" as *;
@use "../../styles/input" as *;
.kima-upload-manager{@include advanced-root;display:grid;gap:var(--kima-space-3);&__list{position:relative;list-style:none;padding:0;margin:0;display:grid;gap:var(--kima-space-2)}li{@include input-surface;display:flex;align-items:center;justify-content:space-between;gap:var(--kima-space-3);padding:var(--kima-space-3)}&__info{display:grid;min-width:0;flex:1;gap:var(--kima-space-1);strong{overflow-wrap:anywhere}span{font-size:var(--kima-font-size-label-small);color:var(--kima-color-on-surface-variant)}progress{width:100%;accent-color:var(--kima-color-primary)}}&__actions{display:flex;flex-wrap:wrap}}
.kima-upload-manager__list > li.kima-list-enter-active,
.kima-upload-manager__list > li.kima-list-leave-active { transition: opacity var(--kima-duration-medium) var(--kima-curve-standard), transform var(--kima-duration-medium) var(--kima-curve-emphasized); }
.kima-upload-manager__list > li.kima-list-move { transition: transform var(--kima-duration-slow) var(--kima-curve-emphasized); }
</style>
